CREATE FUNCTION c1_private.fail(code text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE=code; END $$;
CREATE FUNCTION c1_private.h(x text) RETURNS bytea LANGUAGE plpgsql IMMUTABLE AS $$ BEGIN IF x IS NULL OR x!~'^[0-9a-f]{64}$' THEN PERFORM c1_private.fail('INVALID_HASH'); END IF; RETURN decode(x,'hex'); END $$;
CREATE FUNCTION c1_private.money(x jsonb,allow_zero boolean DEFAULT false) RETURNS numeric LANGUAGE plpgsql IMMUTABLE AS $$ DECLARE t text; n numeric; BEGIN IF jsonb_typeof(x)<>'string' THEN PERFORM c1_private.fail('INVALID_INTEGER'); END IF;t=x#>>'{}'; IF t!~'^(0|[1-9][0-9]*)$' OR length(t)>78 THEN PERFORM c1_private.fail('INVALID_INTEGER'); END IF;n=t::numeric;IF n>115792089237316195423570985008687907853269984665640564039457584007913129639935 OR (n=0 AND NOT allow_zero) THEN PERFORM c1_private.fail('INVALID_INTEGER'); END IF;RETURN n;END $$;
CREATE FUNCTION c1_private.windows(w jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$ DECLARE p jsonb;last_end integer=-1;a integer;b integer; BEGIN IF jsonb_typeof(w)<>'array' OR jsonb_array_length(w) NOT BETWEEN 1 AND 2 THEN PERFORM c1_private.fail('INVALID_WINDOWS'); END IF;FOR p IN SELECT value FROM jsonb_array_elements(w) LOOP IF jsonb_array_length(p)<>2 OR (p->>0)!~'^(0|[1-9][0-9]*)$' OR (p->>1)!~'^(0|[1-9][0-9]*)$' THEN PERFORM c1_private.fail('INVALID_WINDOWS'); END IF;a=(p->>0)::int;b=(p->>1)::int;IF a<0 OR a>1439 OR b>a+1440 OR b>1440 OR b<=a OR a<last_end THEN PERFORM c1_private.fail('INVALID_WINDOWS');END IF;last_end=b;END LOOP; RETURN true;END $$;
CREATE FUNCTION c1_private.window_end(w jsonb,t bigint) RETURNS bigint LANGUAGE plpgsql IMMUTABLE AS $$ DECLARE p jsonb;s bigint=(t+28800)%86400;base bigint=t-s;BEGIN FOR p IN SELECT value FROM jsonb_array_elements(w) LOOP IF s>=(p->>0)::bigint*60 AND s<(p->>1)::bigint*60 THEN RETURN base+(p->>1)::bigint*60;END IF;END LOOP;RETURN 0;END $$;
CREATE FUNCTION c1_private.guard(n text,risk boolean DEFAULT false,mutation uuid DEFAULT NULL) RETURNS c1_private.deployment LANGUAGE plpgsql AS $$ DECLARE d c1_private.deployment;g c1_private.transaction_guard;BEGIN SELECT * INTO d FROM c1_private.deployment WHERE ns=n;IF NOT FOUND THEN PERFORM c1_private.fail('NOT_FOUND');END IF; SELECT * INTO g FROM c1_private.transaction_guard WHERE ns=n FOR UPDATE;SELECT * INTO d FROM c1_private.deployment WHERE ns=n FOR UPDATE; IF risk AND (d.halt OR d.now<d.clock_floor OR d.now-d.heartbeat>30 OR (g.security_pending IS NOT NULL AND g.security_pending IS DISTINCT FROM mutation) OR g.execution_pending IS NOT NULL) THEN PERFORM c1_private.fail('UNAVAILABLE');END IF;RETURN d;END $$;
CREATE FUNCTION c1_private.auth(n text,q jsonb,mutation boolean DEFAULT false) RETURNS c1_private.sessions LANGUAGE plpgsql AS $$ DECLARE s c1_private.sessions;i c1_private.identities;d c1_private.deployment;BEGIN IF q->>'session_hash' IS NULL THEN PERFORM c1_private.fail('UNAUTHENTICATED');END IF;SELECT * INTO d FROM c1_private.deployment WHERE ns=n; SELECT * INTO s FROM c1_private.sessions WHERE ns=n AND hash=c1_private.h(q->>'session_hash');IF NOT FOUND THEN PERFORM c1_private.fail('UNAUTHENTICATED');END IF; SELECT * INTO i FROM c1_private.identities WHERE ns=n AND subject=s.subject;IF s.revoked OR s.epoch<>d.credential_epoch OR s.identity_revision<>i.revision OR d.now>=s.created+86400 OR d.now>=s.activity+1800 THEN PERFORM c1_private.fail('UNAUTHENTICATED');END IF;IF mutation AND (q->>'csrf_hash' IS NULL OR s.csrf IS DISTINCT FROM c1_private.h(q->>'csrf_hash')) THEN PERFORM c1_private.fail('CSRF');END IF;RETURN s;END $$;
CREATE FUNCTION c1_private.owner_auth(n text,s c1_private.sessions,st text,a text) RETURNS bigint LANGUAGE plpgsql AS $$ DECLARE g c1_private.grants;i c1_private.identities;BEGIN SELECT * INTO i FROM c1_private.identities WHERE ns=n AND subject=s.subject;SELECT * INTO g FROM c1_private.grants WHERE ns=n AND store=st AND subject=s.subject AND action=a;IF NOT FOUND OR NOT g.enabled OR g.email_key<>i.email_key THEN PERFORM c1_private.fail('NOT_FOUND');END IF;RETURN g.revision;END $$;
CREATE FUNCTION c1_private.provenance(n text) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT jsonb_build_object('sourceEpoch',source_epoch,'height',height,'blockHash',parent,'observedAt',heartbeat,'stale',now-heartbeat>30,'halted',halt,'reason',reason,'catalogRevision',catalog_revision) FROM c1_private.deployment WHERE ns=n $$;
CREATE FUNCTION c1_private.term_dto(n text,st text,m text,v bigint) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT jsonb_build_object('store',store,'meal',meal,'version',version,'name',convert_from(name,'UTF8'),'description',convert_from(description,'UTF8'),'price',price::text,'windows',windows,'termsHash','0x'||encode(terms_hash,'hex'),'bodyDigest','0x'||encode(body_digest,'hex'),'imageDigest','0x'||encode(image_digest,'hex'),'available',available) FROM c1_private.terms WHERE ns=n AND store=st AND meal=m AND version=v $$;
CREATE FUNCTION c1_private.idem(n text,s c1_private.sessions,a text,q jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$ DECLARE i c1_private.intents;BEGIN SELECT * INTO i FROM c1_private.intents WHERE ns=n AND principal=s.subject AND action=a AND idem=q->>'key';IF NOT FOUND THEN RETURN NULL;END IF;IF i.client_request IS DISTINCT FROM q->'client' THEN PERFORM c1_private.fail('CONFLICT');END IF;RETURN jsonb_build_object('id',i.id,'stage',i.stage,'result',i.result,'deadline',i.deadline,'replay',true);END $$;
CREATE FUNCTION c1_private.new_intent(n text,s c1_private.sessions,a text,q jsonb,p jsonb,wait_actor boolean DEFAULT false,grant_rev bigint DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql AS $$ DECLARE i uuid=(q->>'new_id')::uuid;d c1_private.deployment;pr bigint;BEGIN SELECT * INTO d FROM c1_private.deployment WHERE ns=n;IF (SELECT count(*) FROM c1_private.intents WHERE ns=n AND stage NOT IN('FINAL_SUCCEEDED','FINAL_REVERT','DEFINITELY_UNEXECUTED'))>=100 THEN PERFORM c1_private.fail('QUEUE_FULL');END IF;IF q->>'key' IS NULL OR length(q->>'key') NOT BETWEEN 16 AND 128 OR q->>'key'!~'^[ -~]+$' THEN PERFORM c1_private.fail('INVALID_KEY');END IF;SELECT revision INTO pr FROM c1_private.payer_bindings WHERE ns=n AND subject=s.subject AND enabled;INSERT INTO c1_private.intents VALUES(n,i,s.subject,a,q->>'key',q->'client',p,s.hash,s.identity_revision,grant_rev,pr,CASE WHEN wait_actor THEN 'WAIT_ACTOR' ELSE 'ACCEPTED' END,NULL,d.now,(p->>'deadline')::bigint);PERFORM c1_private.failpoint(n,'domain_before_outbox');INSERT INTO c1_private.outbox(ns,intent,state) VALUES(n,i,CASE WHEN wait_actor THEN 'WAIT_ACTOR' ELSE 'READY' END);PERFORM c1_private.failpoint(n,'domain_after_outbox');INSERT INTO c1_private.audit(ns,object_id,status,at) VALUES(n,i::text,'ACCEPTED',d.now);RETURN jsonb_build_object('id',i,'stage',CASE WHEN wait_actor THEN 'WAIT_ACTOR' ELSE 'ACCEPTED' END,'deadline',p->'deadline');END $$;
CREATE FUNCTION c1_private.voucher_auth(n text,s c1_private.sessions,id text) RETURNS c1_private.vouchers LANGUAGE plpgsql AS $$ DECLARE v c1_private.vouchers;i c1_private.identities;BEGIN SELECT * INTO i FROM c1_private.identities WHERE ns=n AND subject=s.subject;SELECT * INTO v FROM c1_private.vouchers WHERE ns=n AND c1_private.vouchers.id=voucher_auth.id;IF NOT FOUND OR v.email_key<>i.email_key THEN PERFORM c1_private.fail('NOT_FOUND');END IF;RETURN v;END $$;
CREATE FUNCTION c1_private.voucher_dto(n text,id text) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT jsonb_build_object('id',v.id,'store',v.store,'unit',v.seq,'generation',v.generation::text,'issuedAt',v.issued_at,'expiresAt',v.expires_at,'state',CASE WHEN u.generation<>v.generation THEN 'OLD_GENERATION' ELSE u.bucket END,'locked',u.lock_id IS NOT NULL,'marked',u.marker_id IS NOT NULL,'pending',u.active_op,'accessEpoch',v.access_epoch,'displayEpoch',v.display_epoch,'terms',c1_private.term_dto(n,u.store,u.meal,u.version),'provenance',c1_private.provenance(n)) FROM c1_private.vouchers v JOIN c1_private.units u ON u.ns=v.ns AND u.store=v.store AND u.seq=v.seq WHERE v.ns=n AND v.id=voucher_dto.id $$;
-- Private helper functions receive no PUBLIC EXECUTE.
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA c1_private FROM PUBLIC;

CREATE FUNCTION c1_private.cursor_guard(n text,q jsonb) RETURNS boolean LANGUAGE plpgsql STABLE AS $$ BEGIN IF coalesce((q->>'limit')::int,20) NOT BETWEEN 1 AND 50 THEN PERFORM c1_private.fail('PAGE_LIMIT');END IF;IF q ? 'catalog_snapshot' AND (q->>'catalog_snapshot')::bigint<>(SELECT catalog_revision FROM c1_private.deployment WHERE ns=n) THEN PERFORM c1_private.fail('CURSOR_STALE');END IF;IF q ? 'snapshot' AND (q->>'snapshot')::bigint<>(SELECT height FROM c1_private.deployment WHERE ns=n) THEN PERFORM c1_private.fail('CURSOR_STALE');END IF;RETURN true;END $$;
REVOKE ALL ON FUNCTION c1_private.cursor_guard(text,jsonb) FROM PUBLIC;
